css:
.mobilizesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8eef6;
    background: radial-gradient(1200px 600px at 15% -10%, #142a4a 0%, #0a1424 55%, #060d18 100%);
    border-radius: 18px;
}

.mobilizesim-container * {
    box-sizing: border-box;
}

.mobilizesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0d2747 0%, #123a63 50%, #0e6b7a 100%);
    color: #f1f8fb;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(56, 224, 224, 0.18);
    box-shadow: 0 12px 34px rgba(2, 10, 22, 0.55);
}

.mobilizesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.mobilizesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #7ef0ea;
    background: rgba(56, 224, 224, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.mobilizesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe2ee;
}

.mobilizesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fc0d8;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.mobilizesim-period-counter #currentDay,
.mobilizesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #7ef0ea;
}

.mobilizesim-round-name {
    background: rgba(56, 224, 224, 0.14);
    color: #7ef0ea;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(56, 224, 224, 0.25);
}

.mobilizesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd07a;
    background: rgba(255, 168, 38, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 168, 38, 0.3);
}

.mobilizesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.mobilizesim-status-card {
    background: linear-gradient(180deg, #11243f 0%, #0c1c33 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3a5c;
    box-shadow: 0 6px 18px rgba(2, 10, 22, 0.4);
    border-top: 4px solid #2ec5c5;
}

.mobilizesim-card-ic { border-top-color: #38e0e0; }
.mobilizesim-card-output { border-top-color: #4ade80; }
.mobilizesim-card-adoption { border-top-color: #5aa9ff; }
.mobilizesim-card-tacit { border-top-color: #f0a93c; }

.mobilizesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #88a6c2;
}

.mobilizesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f1f8fb;
}

.mobilizesim-card-ic .mobilizesim-value { color: #38e0e0; }
.mobilizesim-card-output .mobilizesim-value { color: #4ade80; }
.mobilizesim-card-adoption .mobilizesim-value { color: #5aa9ff; }
.mobilizesim-card-tacit .mobilizesim-value { color: #f0a93c; }

.mobilizesim-sublabel {
    font-size: 0.75rem;
    color: #7f9bb5;
    line-height: 1.35;
}

.mobilizesim-card-output.mobilizesim-output-target .mobilizesim-value { color: #4ade80; }
.mobilizesim-card-output.mobilizesim-output-fail .mobilizesim-value { color: #ff6b5e; }
.mobilizesim-card-output.mobilizesim-output-fail { border-top-color: #ff6b5e; }

.mobilizesim-budget-over { border-top-color: #ff6b5e !important; }
.mobilizesim-budget-over .mobilizesim-value { color: #ff6b5e; }

.mobilizesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #0d2747 0%, #0e6b7a 100%);
    color: #eafcff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid rgba(56, 224, 224, 0.2);
}

.mobilizesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #7ef0ea;
}

.mobilizesim-budget-bar.mobilizesim-budget-bar-over #budgetDisplay {
    color: #ff6b5e;
}

.mobilizesim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(180deg, #11243f 0%, #0c1c33 100%);
    border-left: 5px solid #38e0e0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(2, 10, 22, 0.4);
}

.mobilizesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.mobilizesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #7ef0ea;
    margin-bottom: 6px;
}

.mobilizesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d4e3f0;
}

.mobilizesim-briefing-text strong { color: #4ade80; }
.mobilizesim-briefing-text em { color: #ffd07a; font-style: italic; }

.mobilizesim-controls {
    background: linear-gradient(180deg, #11243f 0%, #0b1a30 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5c;
    box-shadow: 0 6px 18px rgba(2, 10, 22, 0.4);
}

.mobilizesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f1f8fb;
    border-bottom: 2px solid #1d3a5c;
    padding-bottom: 8px;
}

.mobilizesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #b8d0e6;
    margin: 14px 0 6px;
}

.mobilizesim-container select,
.mobilizesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #244a72;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0b1c33;
    color: #e8eef6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.mobilizesim-container select:focus,
.mobilizesim-container input[type="number"]:focus {
    outline: none;
    border-color: #38e0e0;
    box-shadow: 0 0 0 3px rgba(56, 224, 224, 0.18);
}

.mobilizesim-container select option {
    background-color: #0b1c33;
    color: #e8eef6;
}

.mobilizesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38e0e0;
}

.mobilizesim-range-readout,
.mobilizesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fc0d8;
    margin-top: 4px;
}

.mobilizesim-range-readout span:last-child,
.mobilizesim-alloc-readout span:nth-child(2) {
    color: #4ade80;
    font-weight: 800;
}

.mobilizesim-hint {
    font-size: 0.8rem;
    color: #7f9bb5;
    margin-top: 4px;
    line-height: 1.4;
}

.mobilizesim-shock {
    background: rgba(255, 107, 94, 0.12);
    border: 1px solid rgba(255, 107, 94, 0.4);
    border-left: 4px solid #ff6b5e;
    color: #ffc9c2;
    border-radius: 9px;
    padding: 10px 14px;
    font-size: 0.9rem;
    font-weight: 600;
    line-height: 1.45;
    margin-bottom: 6px;
}

.mobilizesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.mobilizesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0c1f39;
    border: 1px solid #1d3a5c;
    border-radius: 9px;
    padding: 8px 12px;
}

.mobilizesim-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #b8d0e6;
}

.mobilizesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.mobilizesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.mobilizesim-container .btn-primary {
    background: linear-gradient(135deg, #0e6b7a 0%, #2ec5c5 60%, #38e0e0 100%);
    border: none;
    color: #04222a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(46, 197, 197, 0.32);
}

.mobilizesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.mobilizesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #244a72;
    color: #9fc0d8;
    background: transparent;
}

.mobilizesim-coach {
    background: linear-gradient(135deg, #0d2747 0%, #123a63 100%);
    color: #e8eef6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(56, 224, 224, 0.18);
    box-shadow: 0 8px 22px rgba(2, 10, 22, 0.5);
}

.mobilizesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7ef0ea;
    margin-bottom: 8px;
}

.mobilizesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d4e3f0;
}

.mobilizesim-coach-body strong { color: #4ade80; }
.mobilizesim-coach-body em { color: #ffd07a; font-style: italic; }

.mobilizesim-history,
.mobilizesim-chart {
    background: linear-gradient(180deg, #11243f 0%, #0b1a30 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3a5c;
    box-shadow: 0 6px 18px rgba(2, 10, 22, 0.4);
}

.mobilizesim-history h3,
.mobilizesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f1f8fb;
}

.mobilizesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #d4e3f0;
}

.mobilizesim-container table#usfHistoryTable th {
    background: #0c2240;
    color: #7ef0ea;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1d3a5c;
}

.mobilizesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #16304f;
    color: #cbdbeb;
}

.mobilizesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(12, 31, 57, 0.5);
}

.mobilizesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .mobilizesim-container {
        padding: 14px;
    }
    .mobilizesim-header h1 {
        font-size: 1.7rem;
    }
    .mobilizesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .mobilizesim-value {
        font-size: 2rem;
    }
    .mobilizesim-clock {
        margin-left: 0;
    }
    .mobilizesim-period-counter {
        font-size: 0.88rem;
    }
    .mobilizesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .mobilizesim-alloc-row {
        flex-wrap: wrap;
    }
    .mobilizesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .mobilizesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained) */
.mobilizesim-cm { background:#f5f7fb; color:#171c2b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(23,28,43,0.18); }
.mobilizesim-cm-head { text-align:center; border-bottom:1px solid #d5dcec; padding-bottom:14px; margin-bottom:16px; }
.mobilizesim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5b6580; font-weight:700; }
.mobilizesim-cm-scorewrap { margin:8px 0 2px; }
.mobilizesim-cm-score { font-size:52px; font-weight:800; color:#3a56b0; line-height:1; }
.mobilizesim-cm-score-max { font-size:20px; color:#8791ad; font-weight:600; }
.mobilizesim-cm-grade { font-size:19px; font-weight:700; color:#171c2b; margin-top:4px; }
.mobilizesim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.mobilizesim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.mobilizesim-cm-met { background:#cfe6dc; color:#126a4c; }
.mobilizesim-cm-fail { background:#f2dcd8; color:#9c3a2b; }
.mobilizesim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.mobilizesim-cm-metric { background:#e7ecf7; border-radius:10px; padding:12px 16px; min-width:100px; text-align:center; }
.mobilizesim-cm-metric-val { font-size:22px; font-weight:800; color:#2b3350; }
.mobilizesim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5b6580; margin-top:3px; }
.mobilizesim-cm-insights { background:#e7ecf7; border-radius:10px; padding:14px 18px; }
.mobilizesim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5b6580; font-weight:700; margin-bottom:8px; }
.mobilizesim-cm-insights ul { margin:0; padding-left:18px; }
.mobilizesim-cm-insights li { font-size:14px; line-height:1.5; color:#2b3350; margin-bottom:7px; }

