(function() {
    'use strict';

    class MobilizeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Mobilizing What We Know`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Sendoa Systems, EUR).
            this.START_IC = 22;          // intellectual-capital index (low, with headroom)
            this.START_OUTPUT = 19;      // new-product revenue %, down from 38%
            this.START_ADOPTION = 15;    // real knowledge flow (2021 platform unused)
            this.START_TACIT = 10;       // tacit knowledge captured so far
            this.TARGET_OUTPUT = 30;     // board recovery threshold
            this.BUDGET_CAP = 5.0;       // EUR 5 million, one-year window

            // Concept truths.
            this.TRUE_CONSTRAINT = `human`;   // human + structural together is the real binding gap
            this.TRUE_URGENCY = `tacit`;      // fragile tacit knowledge walking out comes first
        }

        // Locale-aware EUR money formatter. English: "€2.4M" (symbol before).
        // Spanish: "2,4 M€" (symbol after, comma decimal, dot thousands).
        _money(millions) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Math.round(Number(millions) * 10) / 10;
            if (lang === `es`) {
                return v.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + v.toFixed(1) + `M`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ic: this.START_IC,
                    output: this.START_OUTPUT,
                    adoption: this.START_ADOPTION,
                    tacit: this.START_TACIT,
                    budgetUsed: 0,
                    targetMissed: false,
                    theatre: false,
                    icHistory: [this.START_IC],
                    outputHistory: [this.START_OUTPUT],
                    adoptionHistory: [this.START_ADOPTION],
                    tacitHistory: [this.START_TACIT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a middling/neutral mix (NOT the textbook-correct play).
                state.decisions = {
                    constraint: `relational`,
                    urgency: `platform`,
                    rigour: 50,
                    capture: 0.5,
                    platform: 1.0,
                    cop: 0.6,
                    rotation: 0.6,
                    open: 0.6,
                    sequence: `thinall`,
                    incentive: 5,
                    recognition: `activity`,
                    protect: 0.3,
                    safeguard: `none`,
                    redirect: `moreplatform`,
                    measure: `mixed`,
                    pitch: `optimistic`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const con = document.getElementById(`constraintInput`);
                const urg = document.getElementById(`urgencyInput`);
                const rig = document.getElementById(`rigourInput`);
                if (con) decisions.constraint = con.value;
                if (urg) decisions.urgency = urg.value;
                if (rig) decisions.rigour = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`captureInput`, `platformInput`, `copInput`, `rotationInput`, `openInput`];
                const keys = [`capture`, `platform`, `cop`, `rotation`, `open`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const seq = document.getElementById(`sequenceInput`);
                if (seq) decisions.sequence = seq.value;
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0) * 10) / 10;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`); return false;
                }
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
            } else if (round === 3) {
                const inc = document.getElementById(`incentiveInput`);
                const rec = document.getElementById(`recognitionInput`);
                const pr = document.getElementById(`protectInput`);
                const sf = document.getElementById(`safeguardInput`);
                if (inc) decisions.incentive = parseInt(inc.value, 10);
                if (rec) decisions.recognition = rec.value;
                if (pr) decisions.protect = parseFloat(pr.value);
                if (sf) decisions.safeguard = sf.value;
                if (!Number.isFinite(decisions.incentive) || decisions.incentive < 0 || decisions.incentive > 50) {
                    warn(`warn_incentive_range`); return false;
                }
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0) {
                    warn(`warn_protect_negative`); return false;
                }
            } else if (round === 4) {
                const rd = document.getElementById(`redirectInput`);
                const me = document.getElementById(`measureInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rd) decisions.redirect = rd.value;
                if (me) decisions.measure = me.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. adoption = genuine knowledge flow; tacit = fragile know-how secured;
            // ic = intellectual-capital index; activity = vanity activity that lifts nothing real.
            let icDelta = 0, adoptionDelta = 0, tacitDelta = 0, activity = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the binding IC constraint (Common Error 4: hiring as a cure-all).
                if (d.constraint === this.TRUE_CONSTRAINT) {
                    icDelta += 12; adoptionDelta += 6; coachKey = `coach_r1_constraint_right`;
                } else if (d.constraint === `hiring`) {
                    icDelta -= 8; adoptionDelta -= 4; coachKey = `coach_r1_hiring`;
                } else if (d.constraint === `relational`) {
                    icDelta -= 2; coachKey = `coach_r1_relational`;
                } else {
                    icDelta -= 6; adoptionDelta -= 4; coachKey = `coach_r1_even`;
                }

                // Urgency-weighting: fragile tacit knowledge first (Common Error 2).
                if (d.urgency === this.TRUE_URGENCY) {
                    tacitDelta += 12; icDelta += 4;
                    if (d.constraint === this.TRUE_CONSTRAINT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.urgency === `platform`) {
                    tacitDelta -= 4; coachKey = `coach_r1_platformfirst`;
                } else if (d.urgency === `revenue`) {
                    tacitDelta -= 8; icDelta -= 4; coachKey = `coach_r1_revenue`;
                } else {
                    tacitDelta -= 12; icDelta -= 6; coachKey = `coach_r1_none`;
                }

                // Diagnostic rigour (impact × urgency mapping).
                if (d.rigour >= 60) { icDelta += 6; }
                else if (d.rigour <= 25) { icDelta -= 6; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.constraint === this.TRUE_CONSTRAINT && d.urgency === this.TRUE_URGENCY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate EUR 5M (Common Errors 2, 3, 4). Concentrate on urgent + high-impact;
                // even-spreading leaves every programme below the adoption threshold.
                const cap = d.capture, plat = d.platform, cop = d.cop, rot = d.rotation, open = d.open;
                spend = cap + plat + cop + rot + open;
                const total = spend;

                // Expert-capture funds the urgent, irreversible tacit-knowledge loss.
                if (cap >= 0.9) { tacitDelta += 18; icDelta += 6; }
                else if (cap >= 0.6) { tacitDelta += 11; icDelta += 3; }
                else if (cap >= 0.3) { tacitDelta += 4; }
                else { tacitDelta -= 10; coachKey = `coach_r2_nocapture`; }

                // Platform relaunch helps structural capital only when properly resourced,
                // but adoption depends on incentives (Round 3), so it is not enough alone.
                if (plat >= 1.4) { icDelta += 7; adoptionDelta += 3; }
                else if (plat >= 0.8) { icDelta += 4; adoptionDelta += 1; }
                else if (plat > 0) { icDelta += 1; }

                // Communities of practice — cheap, adoption-driven knowledge flow.
                if (cop >= 0.6) { adoptionDelta += 7; icDelta += 3; }
                else if (cop > 0) { adoptionDelta += 3; icDelta += 1; }

                // Cross-unit rotation breaks silos (structural), slower payoff.
                if (rot >= 0.8) { icDelta += 6; adoptionDelta += 3; }
                else if (rot > 0) { icDelta += 2; }

                // Open innovation builds relational capital — useful, but not the binding gap.
                if (open >= 1.2) { icDelta += 5; }
                else if (open > 0) { icDelta += 2; }

                // Even-spreading penalty: every mechanism funded thinly so none reaches the
                // adoption threshold (Common Error 3).
                const funded = [cap, plat, cop, rot, open].filter((v) => v > 0).length;
                const concentration = funded > 0 ? Math.max(cap, plat, cop, rot, open) / total : 0;
                if (funded === 5 && concentration < 0.27) {
                    icDelta -= 16; adoptionDelta -= 12; tacitDelta -= 8; activity += 12; coachKey = `coach_r2_evenspread`;
                } else if (cap >= 0.9 && (plat >= 0.8 || cop >= 0.6)) {
                    if (coachKey === `coach_default`) coachKey = `coach_r2_focused`;
                }

                // Sequencing.
                switch (d.sequence) {
                    case `urgentfirst`: tacitDelta += 6; icDelta += 3; if (cap >= 0.9) coachKey = `coach_r2_urgentfirst`; break;
                    case `platformfirst`: adoptionDelta -= 4; tacitDelta -= 3; coachKey = `coach_r2_platformseq`; break;
                    case `thinall`: icDelta -= 4; adoptionDelta -= 3; activity += 4; break;
                }

                summaryKey = (cap >= 0.9 && concentration >= 0.27 && d.sequence !== `platformfirst`) ? `sum_r2_good` : ((funded === 5 && concentration < 0.27) ? `sum_r2_even` : `sum_r2_weak`);
            } else if (round === 3) {
                // Incentives decide whether knowledge actually flows (Common Errors 1 & 5).
                // Sweet spot ~15-25%; too low = the 2021 failure; too high = delivery craters.
                if (d.incentive >= 15 && d.incentive <= 25) {
                    adoptionDelta += 14; icDelta += 5; coachKey = `coach_r3_sweetspot`;
                } else if (d.incentive >= 10 && d.incentive <= 30) {
                    adoptionDelta += 9; icDelta += 3;
                } else if (d.incentive <= 5) {
                    adoptionDelta -= 10; activity += 4; coachKey = `coach_r3_toolow`;
                } else { // > 30: over-rewarding sharing craters delivery
                    adoptionDelta += 2; icDelta -= 8; activity += 10; coachKey = `coach_r3_toohigh`;
                }

                // What behaviour is rewarded — reuse + impact, not raw activity, not status quo.
                switch (d.recognition) {
                    case `reuse`: adoptionDelta += 10; icDelta += 5; if (d.incentive >= 15 && d.incentive <= 25) coachKey = `coach_r3_reuse`; break;
                    case `activity`: adoptionDelta -= 2; activity += 10; coachKey = `coach_r3_activity`; break;
                    case `shiponly`: adoptionDelta -= 12; icDelta -= 4; coachKey = `coach_r3_shiponly`; break;
                }

                // Protected time + curation ownership — adoption, not purchase.
                spend = d.protect;
                if (d.protect >= 0.3) { adoptionDelta += 8; icDelta += 4; tacitDelta += 4; }
                else if (d.protect >= 0.1) { adoptionDelta += 3; icDelta += 1; }
                else { adoptionDelta -= 8; coachKey = `coach_r3_noprotect`; }

                // Safeguards so sharing serves innovation, not becomes the goal.
                if (d.safeguard === `outcome`) { icDelta += 4; adoptionDelta += 2; }
                else { activity += 6; if (d.incentive > 30) icDelta -= 2; }

                summaryKey = (d.incentive >= 15 && d.incentive <= 25 && d.recognition === `reuse` && d.protect >= 0.3 && d.safeguard === `outcome`) ? `sum_r3_good` : (d.incentive <= 5 || d.recognition === `shiponly` ? `sum_r3_dead` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover & commit: absorb the mid-year shock, measure output not activity.
                switch (d.redirect) {
                    case `accelerate`: tacitDelta += 14; icDelta += 6; adoptionDelta += 3; coachKey = `coach_r4_accelerate`; break;
                    case `moreplatform`: adoptionDelta -= 4; activity += 8; coachKey = `coach_r4_moreplatform`; break;
                    case `ignore`: tacitDelta -= 12; icDelta -= 6; coachKey = `coach_r4_ignore`; break;
                }

                // Measure innovation OUTPUT, not vanity activity (Common Error 5).
                switch (d.measure) {
                    case `outcomes`: icDelta += 8; adoptionDelta += 6; if (d.redirect === `accelerate`) coachKey = `coach_r4_outcomes`; break;
                    case `mixed`: icDelta += 2; activity += 4; coachKey = `coach_r4_mixed`; break;
                    case `activity`: icDelta -= 6; activity += 14; adoptionDelta -= 4; coachKey = `coach_r4_activity`; break;
                }

                // The board pitch.
                switch (d.pitch) {
                    case `honest`: icDelta += 8; adoptionDelta += 5; if (d.measure === `outcomes`) coachKey = `coach_r4_honest`; break;
                    case `optimistic`: activity += 8; adoptionDelta -= 4; coachKey = `coach_r4_optimistic`; break;
                    case `buy`: icDelta -= 14; adoptionDelta -= 10; tacitDelta -= 6; coachKey = `coach_r4_buy`; break;
                }

                // Conviction nudges intellectual-capital traction.
                icDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.redirect === `accelerate` && d.measure === `outcomes` && d.pitch === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget spans rounds 2 and 3; capped at EUR 5M).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;

            // Intellectual-capital index, adoption and tacit capture move on their deltas.
            ds.ic = Math.max(0, Math.min(100, ds.ic + icDelta));
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionDelta));
            ds.tacit = Math.max(0, Math.min(100, ds.tacit + tacitDelta));

            // Innovation output (new-product revenue %) is driven by GENUINE mobilization —
            // intellectual capital, adoption and captured tacit knowledge — NOT by vanity activity.
            const mobilization = (Math.max(0, icDelta) * 0.45) + (Math.max(0, adoptionDelta) * 0.40) + (Math.max(0, tacitDelta) * 0.30);
            const drag = (Math.min(0, icDelta) * 0.30) + (Math.min(0, adoptionDelta) * 0.25);
            let outputDelta = mobilization * 0.30 + drag * 0.30 - activity * 0.05;
            ds.output = Math.max(0, Math.min(100, ds.output + outputDelta));

            // Knowledge theatre: lots of activity while real output stays stalled.
            if (activity >= 12 && ds.output < this.TARGET_OUTPUT - 6) ds.theatre = true;

            ds.icHistory.push(Math.round(ds.ic));
            ds.outputHistory.push(Math.round(ds.output));
            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.tacitHistory.push(Math.round(ds.tacit));

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            if (round === this.ROUNDS.length && ds.output < this.TARGET_OUTPUT) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                ic: Math.round(ds.ic),
                icDelta: Math.round(icDelta),
                output: Math.round(ds.output),
                outputDelta: Math.round(outputDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionDelta),
                tacit: Math.round(ds.tacit),
                tacitDelta: Math.round(tacitDelta),
                budgetUsed: ds.budgetUsed,
                theatre: ds.theatre,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
