            uiManager.bind(`icDisplay`, `domainState.ic`, (v) => Math.round(v));
            uiManager.bind(`outputDisplay`, `domainState.output`, (v) => {
                const card = document.querySelector(`.mobilizesim-card-output`);
                if (card) {
                    card.classList.toggle(`mobilizesim-output-target`, Number(v) >= this.TARGET_OUTPUT);
                    card.classList.toggle(`mobilizesim-output-fail`, Number(v) < this.TARGET_OUTPUT);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`adoptionDisplay`, `domainState.adoption`, (v) => Math.round(v));
            uiManager.bind(`tacitDisplay`, `domainState.tacit`, (v) => Math.round(v));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.mobilizesim-budget-bar`);
                if (bar) bar.classList.toggle(`mobilizesim-budget-bar-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return this._money(v) + ` / ` + this._money(this.BUDGET_CAP);
            });

            const self = this;

            // Rigour slider readout.
            const rig = document.getElementById(`rigourInput`);
            const rigReadout = document.getElementById(`rigourReadout`);
            if (rig && rigReadout) {
                rigReadout.textContent = rig.value;
                rig.addEventListener(`input`, function() { rigReadout.textContent = rig.value; });
            }

            // Incentive slider readout.
            const inc = document.getElementById(`incentiveInput`);
            const incReadout = document.getElementById(`incentiveReadout`);
            if (inc && incReadout) {
                incReadout.textContent = inc.value;
                inc.addEventListener(`input`, function() { incReadout.textContent = inc.value; });
            }

            // Allocation live total (EUR 5M cap).
            const allocIds = [`captureInput`, `platformInput`, `copInput`, `rotationInput`, `openInput`];
            const spendReadout = document.getElementById(`spendReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (spendReadout) spendReadout.textContent = self._money(total).replace(/\s?M€|€|M/g, ``).trim() || total.toFixed(1);
                const bar = document.querySelector(`.mobilizesim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#ff6b5e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

