        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.outputHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                mobilizeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.outputHistory },
                        { data: ds.icHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.tacitHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const ic = Math.round(ds.ic);
            const output = Math.round(ds.output);
            const adoption = Math.round(ds.adoption);
            const tacit = Math.round(ds.tacit);
            return Math.round(output * 0.30 + ic * 0.30 + adoption * 0.20 + tacit * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const ic = Math.round(ds.ic);
            const output = Math.round(ds.output);
            const adoption = Math.round(ds.adoption);
            const tacit = Math.round(ds.tacit);

            const hitTarget = output >= this.TARGET_OUTPUT;
            // Top-tier gate: only a focused, urgency-weighted, incentive-aligned play clears these
            // floors. A single classic Common Error dents one KPI enough to drop below the gate,
            // so hiring-as-a-cure-all, the repeated-2021 incentive failure, activity-led measurement
            // and over-rewarding sharing all fall short of "Knowledge Mobilized".
            const realMobilization = adoption >= 65 && tacit >= 60 && ic >= 65;
            const theatre = ds.theatre || (adoption < 45 && output < this.TARGET_OUTPUT);
            const composite = this._composite(ds);

            let performanceKey = `grade_stalled`;
            if (hitTarget && realMobilization && composite >= 70) performanceKey = `grade_mobilized`;
            else if (hitTarget && realMobilization) performanceKey = `grade_recovering`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (theatre) performanceKey = `grade_theatre`;
            else if (output > this.START_OUTPUT + 5) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);
            const met = hitTarget && realMobilization && composite >= 70;

            const insights = [];
            if (hitTarget && realMobilization) insights.push(window.mySimulation.t(`insight_mobilized`));
            else if (theatre) insights.push(window.mySimulation.t(`insight_theatre`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (tacit < 45) insights.push(window.mySimulation.t(`insight_tacitlost`));
            if (adoption < 45) insights.push(window.mySimulation.t(`insight_lowadoption`));
            if (output >= 38) insights.push(window.mySimulation.t(`insight_restored`));
            if (hitTarget && realMobilization && tacit >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                ic: ic,
                output: output,
                adoption: adoption,
                tacit: tacit,
                hitTarget: hitTarget,
                theatre: theatre,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                realMobilization: realMobilization,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="mobilizesim-cm-badge ` + (s.met ? `mobilizesim-cm-met` : `mobilizesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.hitTarget === false) badges.push(`<span class="mobilizesim-cm-badge mobilizesim-cm-fail">` + t(`cm_fail_target`) + `</span>`);
            if (s.realMobilization === false) badges.push(`<span class="mobilizesim-cm-badge mobilizesim-cm-fail">` + t(`cm_fail_mobilization`) + `</span>`);
            if (s.theatre) badges.push(`<span class="mobilizesim-cm-badge mobilizesim-cm-fail">` + t(`cm_fail_theatre`) + `</span>`);
            const kpi = (label, val) => `<div class="mobilizesim-cm-metric"><div class="mobilizesim-cm-metric-val">` + val + `</div><div class="mobilizesim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_output`), (s.output != null ? Math.round(s.output) : 0) + `%`)
                + kpi(t(`cm_ic`), (s.ic != null ? Math.round(s.ic) : 0))
                + kpi(t(`cm_adoption`), (s.adoption != null ? Math.round(s.adoption) : 0))
                + kpi(t(`cm_tacit`), (s.tacit != null ? Math.round(s.tacit) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="mobilizesim-cm">`
                + `<div class="mobilizesim-cm-head"><div class="mobilizesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="mobilizesim-cm-scorewrap"><span class="mobilizesim-cm-score">` + score + `</span><span class="mobilizesim-cm-score-max">/100</span></div>`
                + `<div class="mobilizesim-cm-grade">` + grade + `</div>`
                + `<div class="mobilizesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="mobilizesim-cm-metrics">` + kpis + `</div>`
                + `<div class="mobilizesim-cm-insights"><div class="mobilizesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.theatre) return window.mySimulation.t(`hint_theatre`);
            if (ds.tacit < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_tacit`);
            if (ds.adoption < 35) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.output < 24) return window.mySimulation.t(`hint_behind`);
            if (ds.output >= this.TARGET_OUTPUT && ds.adoption >= 55 && ds.tacit >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

