                    mech_open:              `Open innovation — customers and universities`,
                    seq_urgentfirst:        `Urgent-first — capture the at-risk tacit knowledge now, build the rest in parallel`,
                    seq_platformfirst:      `Platform-first — relaunch the system, then everything else follows`,
                    seq_thinall:            `A little of everything from day one — keep all five moving together`,

                    r3_incentive_label:     `How heavily does knowledge-sharing weigh in each engineer's bonus and promotion? (%)`,
